{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket lacks server-side encryption",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption enabled. Without encryption, sensitive data stored in the bucket could be exposed if unauthorized access occurs."
    },
    {
      "check_id": "CKV_AWS_52",
      "title": "S3 bucket lacks logging configuration",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have logging enabled. Without logging, it is difficult to track access and changes to the bucket, which can hinder incident response and auditing."
    },
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 bucket lacks versioning",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "LOW",
      "explanation": "The S3 bucket does not have versioning enabled. Without versioning, accidental deletions or overwrites of objects cannot be easily recovered."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"AES256\"\n      }\n    }\n  }\n\n  logging {\n    target_bucket = \"logging-bucket-name\"\n    target_prefix = \"cloudtrail-logs/\"\n  }\n\n  versioning {\n    enabled = true\n  }\n}",
  "fix_summary": "Enabled server-side encryption with AES256 to protect data at rest. Added logging configuration to track access and changes to the bucket. Enabled versioning to allow recovery from accidental deletions or overwrites."
}
